"""Render inputs/dossier/DOSSIER-generated.md from live-capture.json and the live-app source."""
import json, pathlib, re
HERE = pathlib.Path(__file__).resolve().parents[1]
cap = json.loads((HERE / "inputs/dossier/live-capture.json").read_text())
src = HERE / "inputs/live-app/src"
md = ["# S02 live-app capture (generated)", "", "Generated by `tools/build_dossier.py` from `live-capture.json` (Playwright run against https://it-beginner-platform-jqu1.arcada.app) and the decompiled source in `inputs/live-app/src`.", "",
      "## Header behaviour by viewport", "", "| Width | Header height | Desktop nav | Header row scroll width | Document width | Wrapped labels |", "| --- | --- | --- | --- | --- | --- |"]
for w, h in cap["header"].items():
    md.append(f"| {w} | {h['headerHeight']} | {'visible' if h['navVisible'] else 'hidden'} | {h['rowScrollWidth']} | {h['docWidth']} | {', '.join(h['wrapped']) or 'none'} |")
md += ["", "A document width above the viewport width means the page scrolls sideways: the header row does not fit at 1024, 1280 or 1440px, and the page is 8px too wide at 360px.", ""]
for w in ("1440", "390"):
    md += [f"## Routes at {w}px", "", "| Route | Region | Height | Components | Top fonts (family weight: count) | Font sizes by use | Top radii | Gradients | Blurs | Uppercase text nodes | Running animations |", "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |"]
    for r, v in cap["routes"].items():
        for s in v[w]:
            if s["region"] != "main" and r != "/": continue
            f = ", ".join(f"{a}: {b}" for a, b in s["fonts"][:4]); z = ", ".join(a for a, _ in s["sizes"][:6])
            rad = ", ".join(("pill" if a.startswith("3.4") else a) for a, _ in s["radii"][:4])
            an = ", ".join(f"{k} x{n}" for k, n in s["animations"].items())
            md.append(f"| {r} | {s['region']} | {s['height']} | {' '.join(c.split('/')[-1] for c in s['components'])} | {f} | {z} | {rad} | {s['gradients']} | {s['blurs']} | {s['uppercase']} | {an} |")
    md.append("")
md += ["## Class inventory (from source)", "", "| File | Lines | `text-[10px]`/`text-[11px]`/`text-xs` | `uppercase` | `bg-gradient-*` | `animate-*` | `shadow-*` glow | `font-bold`/`extrabold`/`black` | lucide icons imported | emoji in JSX |", "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |"]
SMALL = re.compile(r"text-\[1[01]px\]|text-xs"); GLOW = re.compile(r"shadow-[a-z]+-\d+/")
EMOJI = re.compile("[\U0001F300-\U0001FAFF\u2600-\u27BF\u2B50\u26A1]")
for p in sorted(src.rglob("*.tsx")):
    t = p.read_text(); imp = re.search(r'import \{([^}]*)\} from "lucide-react"', t)
    md.append(f"| {p.relative_to(src)} | {t.count(chr(10))} | {len(SMALL.findall(t))} | {t.count('uppercase')} | {t.count('bg-gradient-')} | {' '.join(sorted(set(re.findall(r'animate-[a-z-]+', t))))} | {len(GLOW.findall(t))} | {len(re.findall(r'font-(?:bold|extrabold|black)', t))} | {len(imp.group(1).split(',')) if imp else 0} | {len(EMOJI.findall(t))} |")
md += ["", "## Copy, verbatim (innerText at 1440px)", ""]
for r, v in cap["routes"].items():
    for s in v["1440"]:
        if s["region"] != "main" and r != "/": continue
        md += [f"### {r} · {s['region']}", "", "```text", s["text"], "```", ""]
(HERE / "inputs/dossier/DOSSIER-generated.md").write_text("\n".join(md))
